class TestSeleniumWebForm(TestBase):
    """Demo test for Selenium Web Form"""
    @pytest.mark.parametrize("search_term", ["Selenium", "Python", "PyTest"])
    def test_selenium_form(self, search_term):
        """Parametrization using decorators"""
        driver = self.driver
        driver.get("https://www.selenium.dev/selenium/web/web-form.html")
        title = driver.title
        assert title == "Web form"
        driver.implicitly_wait(5)

class DriverFactory:
    """# Driver Factory for Selenium WebDriver
    - Singleton instance
    - Can create instance for specific driver such as Chrome or Firefox
    """
    instance = None
    driver = None
    def __new__(cls):
        if cls.instance is None:
            cls.instance = super(DriverFactory, cls).__new__(cls)
